INSERT INTO category_translation (id, category_id, language, name, created_at, updated_at)
SELECT gen_random_uuid(), c.category_id, x.lang,
       CASE x.lang WHEN 'fr' THEN tr.fr WHEN 'de' THEN tr.de WHEN 'it' THEN tr.it ELSE tr.nl END,
       now(), now()
FROM category_translation c
JOIN tr ON tr.en = c.name
CROSS JOIN (VALUES ('fr'),('de'),('it'),('nl')) AS x(lang)
WHERE c.language = 'en'
  AND NOT EXISTS (SELECT 1 FROM category_translation e
                  WHERE e.category_id = c.category_id AND e.language = x.lang);
